const express = require('express');
const { TenantRealmDirectory } = require('../services/realm');

const app = express();
app.use(express.json());

app.post('/api/okta/hooks/registration', async (req, res) => {
  const hookSecret = req.headers['x-okta-registration-token'];
  if (hookSecret !== process.env.OKTA_REGISTRATION_TOKEN) {
    return res.status(401).json({ error: 'Unauthorized Okta registration hook' });
  }

  const { userProfile } = req.body.data;
  const targetTenantSlug = userProfile.targetTenantSlug;
  const emailDomain = userProfile.email.split('@')[1];

  // Enforce domain whitelist verification for the target tenant
  const allowedDomains = await TenantRealmDirectory.getAllowedDomains(targetTenantSlug);
  if (!allowedDomains || !allowedDomains.includes(emailDomain)) {
    return res.status(403).json({
      error: {
        errorSummary: 'Registration rejected: email domain not authorized for target tenant'
      }
    });
  }

  await TenantRealmDirectory.provisionMember(targetTenantSlug, {
    email: userProfile.email,
    firstName: userProfile.firstName,
    lastName: userProfile.lastName
  });

  res.json({
    commands: [
      {
        type: 'com.okta.user.profile.update',
        value: { tenantAssigned: targetTenantSlug }
      }
    ]
  });
});

app.listen(9006);
